effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }


   /////////////////////////

    float squared(float value) { return value * value; }

    float getAmp(float frequency) { return texture2DCv(black.texture, vec2(frequency / 512.0, 0)).x; }

    float getWeight(float f) {
        return (+ getAmp(f-2.0) + getAmp(f-1.0) + getAmp(f+2.0) + getAmp(f+1.0) + getAmp(f)) / 5.0; }

    void main ()
    {
        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

        highp mat3 rgb2yuv = mat3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );
            highp mat3 yuv2rgb = mat3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );
            float rad = hue * 0.0174533;
            highp mat3 huemat = mat3(
                1.0,  0.0,       0.0,
                0.0,  cos(rad),  sin(rad),
                0.0,  -sin(rad), cos(rad)
            );

        /////////////////////////

    	vec4 result;

    	// vec2 uvTrue = sampleCoord;

    	vec2 uvTrue;
        uvTrue = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        uvTrue.y *=acLayerSize.y/acLayerSize.x;

        vec2 uv = uvTrue;
        // vec2 uv = -1.0 + 2.0 * uvTrue;
        uv /= scale;
        uv += position*vec2(-1.,1.)/500.;
        uv.x *= acLayerSize.x/acLayerSize.y;
        uv *= rot2m(angle*0.0174533);

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        uv /= scaleVec;

    	float lineIntensity;
        float glowWidth;
        vec3 color = vec3(0.0);

    	for(float i = 0.0; i < AMOUNT; i++) {

    		uv.y += (0.2 * sin(uv.x + i/7.0 - progressa * 0.6));
            float Y = uv.y + getWeight(squared(i) * 20.0) *
                (texture2DCv(black.texture, vec2(uvTrue.x, 1)).x - 0.5);
            // lineIntensity = 0.4 + squared(1.6 * abs(mod(uvTrue.x + i / 1.3 + progressb + 2.0) - 1.0)) + (offset * vec2(-1.,1.))/1000.0;
            lineIntensity = 0.4 + squared(1.6 * abs(mod(uvTrue.x + i / 1.3 + progressb,2.0) - 1.0));
    		glowWidth = abs(lineIntensity / (150.0 * Y));
    		color += vec3(glowWidth * (luminance + sin(2.0 * 1.0)), glowWidth * (luminance - sin(0.0 * 0.6)), glowWidth * (luminance - cos(0.0 * 1.0)));
    	}	

    	result = vec4(color, 1.0);
    	result *= 1.0;

            vec4 huecolor;
    	    highp vec3 rgb = result.rgb;
            lowp float a = result.a;
            highp vec3 yuv = rgb * rgb2yuv;

            float origSat = min(1.0,length(yuv.yz)*2.5); //
            vec2 satUV = yuv.yz * 1.0;
            yuv.yz = mix(satUV,yuv.yz,origSat);

            yuv.yz = yuv.yz * 0.0;
            rgb = yuv * yuv2rgb;
            huecolor = vec4(rgb,a);

    	    huecolor.rgb *= colorkey.rgb;
    	    huecolor.rgb *= huemat;
            // yuv = yuv * huemat;


        vec4 factor = mix(texColor,huecolor, alpha);
        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            factor *= texColor.a;
            resultfinal = factor + (texColor*(1.0-factor.a));
        } else if( blendMode==1 ) {         // multiply
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    }
